#[repr(u8)]
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Suit { Clubs, Diamonds, Hearts, Spades }

fn parse(raw: u8) -> Result<Suit, InvalidSuit> {
    match raw {              // fallible, explicit: never `as`
        0 => Ok(Suit::Clubs),
        1 => Ok(Suit::Diamonds),
        _ => Err(InvalidSuit),
    }
}
